using u16 = unsigned short;
using u32 = unsigned int;
using u64 = unsigned long long;
template<typename T> struct be_t {
    T data;
    constexpr operator T() const noexcept {
        if constexpr(sizeof(T) == 2) return __builtin_bswap16(data);
        else return __builtin_bswap32(data);
    }
};
	template <typename T>
	const T& min_max(T& min, T& max, const T& value)
	{
		if (value < min)
			min = value;

		if (value > max)
			max = value;

		return value;
	}

	struct untouched_impl
	{
		template <typename T>
		static u64 upload_untouched_naive(const be_t<T>* src, T* dst, u32 count)
		{
			u32 written = 0;
			T max_index = 0;
			T min_index = -1;

			while (count--)
			{
				T index = src[written];
				dst[written++] = min_max(min_index, max_index, index);
			}

			return (u64{max_index} << 32) | u64{min_index};
		}

};

extern "C" u64 upload16(const be_t<u16>* src, u16* dst, u32 n) {
    return untouched_impl::upload_untouched_naive(src, dst, n);
}
extern "C" u64 upload32(const be_t<u32>* src, u32* dst, u32 n) {
    return untouched_impl::upload_untouched_naive(src, dst, n);
}
